/**
 * converters/langgraph-converter.ts — Synova.yml → LangGraph JSON 转换器
 *
 * 将 Synova 团队蓝图转换为 LangGraph StateGraph 配置，让用户在不依赖
 * OpenClaw Gateway 的环境中至少能导入团队结构和协作拓扑。
 *
 * 映射规则：
 *   Synova.team.roles[]        → LangGraph nodes (AgentState nodes)
 *   Synova.team.roles[].skills → LangGraph tools
 *   Synova.team.protocol       → LangGraph edges + config
 *   Synova.role.genome         → LangGraph node system_prompt
 *
 * 输出兼容 LangGraph Python SDK (langgraph>=0.2.0)。
 */
import type { SynovaYml } from '../synova-yml-serializer';
export interface LangGraphNode {
    id: string;
    type: 'agent' | 'tool' | 'human';
    label: string;
    systemPrompt: string;
    tools: string[];
    metadata: {
        governanceLayer: number;
        cognitiveMode: string;
        decisionStyle: string;
        antiPatterns: string[];
    };
}
export interface LangGraphEdge {
    source: string;
    target: string;
    condition: string | null;
    label: string;
    weight: number;
}
export interface LangGraphTool {
    name: string;
    description: string;
    category: string;
    steps: string[];
    requiresApproval: string[];
}
export interface LangGraphConfig {
    schemaVersion: string;
    graphName: string;
    description: string;
    nodes: LangGraphNode[];
    edges: LangGraphEdge[];
    tools: LangGraphTool[];
    state: {
        channels: string[];
        sharedKeys: string[];
    };
    entryPoint: string;
    config: {
        mode: string;
        topology: string;
        authorityGovernance: string;
        maxIterations: number;
        approvalChain: string[];
    };
}
export declare function synovaToLangGraph(yml: SynovaYml): LangGraphConfig;
export declare function langGraphToJSON(config: LangGraphConfig): string;
export declare function langGraphToPython(config: LangGraphConfig): string;
